}

extern "C" int ib_metal_attention_block_int8(ib_metal_ctx *ctx,
                                               const void *q_fp32,
                                               const void *k_fp32,
                                               const void *v_fp32,
                                               void *k_cache_int8,
                                               void *v_cache_int8,
                                               void *k_scales_fp32,
                                               void *v_scales_fp32,
                                               void *scores_fp32,
                                               void *attn_out_fp32,
                                               int n_heads, int n_kv_heads,
                                               int head_dim, int seq_len, int pos)
{
    if (!ctx) return -1;
    if (!q_fp32 || !k_fp32 || !v_fp32 || !k_cache_int8 || !v_cache_int8
        || !k_scales_fp32 || !v_scales_fp32 || !scores_fp32 || !attn_out_fp32) return -1;
    if (n_heads <= 0 || n_kv_heads <= 0 || head_dim <= 0 || seq_len <= 0) return -1;
    if (pos < 0 || pos >= seq_len) return -1;
    if (n_heads % n_kv_heads != 0) return -1;

    @autoreleasepool {
        id<MTLComputePipelineState> ps_write = get_pipeline(ctx, "kv_cache_write_int8");
        id<MTLComputePipelineState> ps_score = get_pipeline(ctx, "attn_scores_qk_int8");
        id<MTLComputePipelineState> ps_smax  = get_pipeline(ctx, "softmax_rows");
        id<MTLComputePipelineState> ps_wv    = get_pipeline(ctx, "attn_weighted_v_int8");
        if (!ps_write || !ps_score || !ps_smax || !ps_wv) return -1;
        auto pick = [&](const void *p) -> id<MTLBuffer> {
            auto it = ctx->buffers.find((void *)p);
            return it == ctx->buffers.end() ? nil : it->second;
        };
        id<MTLBuffer> b_q  = pick(q_fp32);
        id<MTLBuffer> b_k  = pick(k_fp32);
        id<MTLBuffer> b_v  = pick(v_fp32);
        id<MTLBuffer> b_kc = pick(k_cache_int8);
        id<MTLBuffer> b_vc = pick(v_cache_int8);
        id<MTLBuffer> b_ks = pick(k_scales_fp32);
        id<MTLBuffer> b_vs = pick(v_scales_fp32);
        id<MTLBuffer> b_s  = pick(scores_fp32);
        id<MTLBuffer> b_o  = pick(attn_out_fp32);
        if (!b_q || !b_k || !b_v || !b_kc || !b_vc || !b_ks || !b_vs || !b_s || !b_o) {
            fprintf(stderr, "Metal attn_int8: buffer not registered\n");
            return -1;
        }

        uint nh = (uint)n_heads, nkh = (uint)n_kv_heads, hd = (uint)head_dim;
        uint p = (uint)pos, p1 = (uint)pos + 1u;
        float scale = 1.0f / sqrtf((float)head_dim);

        id<MTLCommandBuffer> cb = [ctx->queue commandBuffer];
        /* 1. KV write_int8 — one threadgroup per kv_head, 32 threads. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_write];
            [enc setBuffer:b_k  offset:0 atIndex:0];
            [enc setBuffer:b_v  offset:0 atIndex:1];
            [enc setBuffer:b_kc offset:0 atIndex:2];
            [enc setBuffer:b_vc offset:0 atIndex:3];
            [enc setBuffer:b_ks offset:0 atIndex:4];
            [enc setBuffer:b_vs offset:0 atIndex:5];
            [enc setBytes:&p   length:sizeof(p)   atIndex:6];
            [enc setBytes:&nkh length:sizeof(nkh) atIndex:7];
            [enc setBytes:&hd  length:sizeof(hd)  atIndex:8];
            [enc dispatchThreadgroups:MTLSizeMake(nkh, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
            [enc endEncoding];
        }
        /* 2. Scores_int8. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_score];
            [enc setBuffer:b_q  offset:0 atIndex:0];
            [enc setBuffer:b_kc offset:0 atIndex:1];
            [enc setBuffer:b_ks offset:0 atIndex:2];
            [enc setBuffer:b_s  offset:0 atIndex:3];
            [enc setBytes:&nh length:sizeof(nh) atIndex:4];
            [enc setBytes:&nkh length:sizeof(nkh) atIndex:5];
            [enc setBytes:&hd length:sizeof(hd) atIndex:6];
            [enc setBytes:&p1 length:sizeof(p1) atIndex:7];
            [enc setBytes:&scale length:sizeof(scale) atIndex:8];
            const NSUInteger TG = 128;
            NSUInteger total = (NSUInteger)nh * (NSUInteger)p1;
            NSUInteger n_tg = (total + TG - 1) / TG;
            [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
            [enc endEncoding];
        }
        /* 3. Softmax. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_smax];
            [enc setBuffer:b_s offset:0 atIndex:0];
            [enc setBytes:&p1 length:sizeof(p1) atIndex:1];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nh, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            [enc endEncoding];
        }
        /* 4. Weighted V_int8. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_wv];
            [enc setBuffer:b_s  offset:0 atIndex:0];
            [enc setBuffer:b_vc offset:0 atIndex:1];
            [enc setBuffer:b_vs offset:0 atIndex:2];
            [enc setBuffer:b_o  offset:0 atIndex:3];
            [enc setBytes:&nh length:sizeof(nh) atIndex:4];
            [enc setBytes:&nkh length:sizeof(nkh) atIndex:5];
            [enc setBytes:&hd length:sizeof(hd) atIndex:6];
            [enc setBytes:&p1 length:sizeof(p1) atIndex:7];
            const NSUInteger TG = 64;
            NSUInteger total = (NSUInteger)nh * (NSUInteger)hd;
            NSUInteger n_tg = (total + TG - 1) / TG;
            [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
            [enc endEncoding];
        }
        [cb commit];
        [cb waitUntilCompleted];
        if (cb.status == MTLCommandBufferStatusError) return -1;
    }
    return 0;
}

extern "C" int ib_metal_residual_add(ib_metal_ctx *ctx,
                                       void *a_fp32, const void *b_fp32, int N)
{
    if (!ctx || !a_fp32 || !b_fp32 || N <= 0) return -1;
    @autoreleasepool {
        id<MTLComputePipelineState> ps = get_pipeline(ctx, "residual_add");
        if (!ps) return -1;
        auto pick = [&](const void *p) -> id<MTLBuffer> {
            auto it = ctx->buffers.find((void *)p);
            return it == ctx->buffers.end() ? nil : it->second;
        };
        id<MTLBuffer> b_a = pick(a_fp32);
        id<MTLBuffer> b_b = pick(b_fp32);
        if (!b_a || !b_b) {
            fprintf(stderr, "Metal residual: buffer not registered\n");
            return -1;
        }
        uint N_u = (uint)N;
        id<MTLCommandBuffer> cb = [ctx->queue commandBuffer];
        id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
        [enc setComputePipelineState:ps];
        [enc setBuffer:b_a offset:0 atIndex:0];
        [enc setBuffer:b_b offset:0 atIndex:1];
        [enc setBytes:&N_u length:sizeof(N_u) atIndex:2];
        const NSUInteger TG = 256;
        NSUInteger n_tg = ((NSUInteger)N + TG - 1) / TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
        [enc endEncoding];
        [cb commit];
        [cb waitUntilCompleted];
        if (cb.status == MTLCommandBufferStatusError) return -1;
    }
    return 0;
}

extern "C" int ib_metal_matmul_int8_fp32_in(ib_metal_ctx *ctx,
                                              const void *x_fp32,
                                              const void *weights,
                                              const void *w_scales,
                                              void *out,
                                              int M, int N)
{
    if (!ctx || !x_fp32 || !weights || !w_scales || !out
        || M <= 0 || N <= 0) return -1;
    @autoreleasepool {
        id<MTLComputePipelineState> ps = get_pipeline(ctx, "matmul_int8_fp32_in");
        if (!ps) return -1;
        auto pick = [&](const void *p) -> id<MTLBuffer> {
            auto it = ctx->buffers.find((void *)p);
            return it == ctx->buffers.end() ? nil : it->second;
        };
        id<MTLBuffer> b_w   = pick(weights);
        id<MTLBuffer> b_ws  = pick(w_scales);
        id<MTLBuffer> b_x   = pick(x_fp32);
        id<MTLBuffer> b_out = pick(out);
        if (!b_w || !b_ws || !b_x || !b_out) {
            fprintf(stderr, "Metal matmul_int8: buffer not registered\n");
            return -1;
        }

        uint M_u = (uint)M, N_u = (uint)N;
        id<MTLCommandBuffer> cb = [ctx->queue commandBuffer];
        id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
        [enc setComputePipelineState:ps];
        [enc setBuffer:b_w   offset:0 atIndex:0];
        [enc setBuffer:b_ws  offset:0 atIndex:1];
        [enc setBuffer:b_x   offset:0 atIndex:2];
        [enc setBuffer:b_out offset:0 atIndex:3];
        [enc setBytes:&M_u   length:sizeof(M_u) atIndex:4];
        [enc setBytes:&N_u   length:sizeof(N_u) atIndex:5];
        const NSUInteger SIMDS_PER_TG = 4;
        const NSUInteger TG_THREADS = 32 * SIMDS_PER_TG;
        NSUInteger n_tg = (M + SIMDS_PER_TG - 1) / SIMDS_PER_TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG_THREADS, 1, 1)];
        [enc endEncoding];
        [cb commit];
        [cb waitUntilCompleted];
        if (cb.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "Metal matmul_int8: cmd buffer error: %s\n",
                    [[cb.error localizedDescription] UTF8String]);
            return -1;
        }
    }
    return 0;
}

/* ── Command recorder ─────────────────────────────────────────────── */

struct ib_metal_recorder {
    ib_metal_ctx *ctx;
    id<MTLCommandBuffer> cb;
};

extern "C" ib_metal_recorder *ib_metal_recorder_begin(ib_metal_ctx *ctx) {
    if (!ctx) return nullptr;
    ib_metal_recorder *r = new ib_metal_recorder();
    r->ctx = ctx;
    r->cb = [ctx->queue commandBuffer];
    return r;
}

extern "C" int ib_metal_recorder_commit(ib_metal_recorder *rec) {
    if (!rec) return -1;
    @autoreleasepool {
        [rec->cb commit];
        [rec->cb waitUntilCompleted];
        bool err = (rec->cb.status == MTLCommandBufferStatusError);
        if (err) {
            fprintf(stderr, "Metal recorder: cmd buffer error: %s\n",
                    [[rec->cb.error localizedDescription] UTF8String]);
        }
        rec->cb = nil;  /* let ARC release */
        delete rec;
        return err ? -1 : 0;
    }
}

static id<MTLBuffer> rec_pick(ib_metal_ctx *ctx, const void *p) {
    auto it = ctx->buffers.find((void *)p);
    return it == ctx->buffers.end() ? nil : it->second;
}

/* Range-aware lookup: if `p` is the exact base of a registered MTLBuffer,
 * returns offset 0. Otherwise scans for a buffer whose [base, base+len)
 * range contains `p` and returns the byte offset.
 *
 * This lets recorders accept derived pointers like `q_buf + b * row_size`
 * without the caller needing to know the underlying buffer. The cost is
 * a linear scan over registered buffers — fine because per-recorder-call
 * lookup count is small (≤ 10) and total buffer count is ~ layers × 7
 * which fits in cache. Returns nil + offset 0 on miss. */
static id<MTLBuffer> rec_pick_off(ib_metal_ctx *ctx, const void *p,
                                    NSUInteger *out_offset) {
    if (out_offset) *out_offset = 0;
    if (!p) return nil;
    auto it = ctx->buffers.find((void *)p);
    if (it != ctx->buffers.end()) return it->second;
    uintptr_t pp = (uintptr_t)p;
    for (auto &kv : ctx->buffers) {
        uintptr_t base = (uintptr_t)kv.first;
        NSUInteger len = [kv.second length];
        if (pp >= base && pp < base + len) {
            if (out_offset) *out_offset = (NSUInteger)(pp - base);
            return kv.second;
        }
    }
    return nil;
}

extern "C" int ib_metal_rec_rmsnorm_fp16(ib_metal_recorder *rec,
                                           const void *x_fp32,
                                           const void *weight_fp16,
                                           void *out_fp32,
                                           int N, float eps)
{
    if (!rec || !x_fp32 || !weight_fp16 || !out_fp32 || N <= 0) return -1;
    id<MTLComputePipelineState> ps = get_pipeline(rec->ctx, "rmsnorm_fp16");
    if (!ps) return -1;
    NSUInteger ox = 0, ow = 0, oo = 0;
    id<MTLBuffer> b_x   = rec_pick_off(rec->ctx, x_fp32, &ox);
    id<MTLBuffer> b_w   = rec_pick_off(rec->ctx, weight_fp16, &ow);
    id<MTLBuffer> b_out = rec_pick_off(rec->ctx, out_fp32, &oo);
    if (!b_x || !b_w || !b_out) return -1;
    uint N_u = (uint)N;
    float eps_v = eps;
    id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
    [enc setComputePipelineState:ps];
    [enc setBuffer:b_x   offset:ox atIndex:0];
    [enc setBuffer:b_w   offset:ow atIndex:1];
    [enc setBuffer:b_out offset:oo atIndex:2];
    [enc setBytes:&N_u   length:sizeof(N_u)   atIndex:3];
    [enc setBytes:&eps_v length:sizeof(eps_v) atIndex:4];
    [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
          threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    [enc endEncoding];
    return 0;
}

extern "C" int ib_metal_rec_residual_add(ib_metal_recorder *rec,
                                           void *a_fp32, const void *b_fp32, int N)
{
    if (!rec || !a_fp32 || !b_fp32 || N <= 0) return -1;
    id<MTLComputePipelineState> ps = get_pipeline(rec->ctx, "residual_add");
    if (!ps) return -1;
    NSUInteger oa = 0, ob = 0;
    id<MTLBuffer> b_a = rec_pick_off(rec->ctx, a_fp32, &oa);
    id<MTLBuffer> b_b = rec_pick_off(rec->ctx, b_fp32, &ob);
    if (!b_a || !b_b) return -1;
    uint N_u = (uint)N;
    id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
    [enc setComputePipelineState:ps];
    [enc setBuffer:b_a offset:oa atIndex:0];
    [enc setBuffer:b_b offset:ob atIndex:1];
    [enc setBytes:&N_u length:sizeof(N_u) atIndex:2];
    const NSUInteger TG = 256;
    NSUInteger n_tg = ((NSUInteger)N + TG - 1) / TG;
    [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
          threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
    [enc endEncoding];
    return 0;
}

extern "C" int ib_metal_rec_matmul_w4a8_fp32_in(ib_metal_recorder *rec,
                                                  const void *x_fp32,
                                                  const void *weights,
                                                  const void *w_scales,
                                                  void *out,
                                                  void *scratch_x_q,
                                                  void *scratch_x_scales,
                                                  int M, int N)
{
    if (!rec || !x_fp32 || !weights || !w_scales || !out
        || !scratch_x_q || !scratch_x_scales || M <= 0 || N <= 0) return -1;
    id<MTLComputePipelineState> ps_q  = get_pipeline(rec->ctx, "quantize_input_int8_g128");
    id<MTLComputePipelineState> ps_mm = get_pipeline(rec->ctx, "matmul_w4a8");
    if (!ps_q || !ps_mm) return -1;

    id<MTLBuffer> b_x   = rec_pick(rec->ctx, x_fp32);
    id<MTLBuffer> b_w   = rec_pick(rec->ctx, weights);
    id<MTLBuffer> b_ws  = rec_pick(rec->ctx, w_scales);
    id<MTLBuffer> b_out = rec_pick(rec->ctx, out);
    id<MTLBuffer> b_xq  = rec_pick(rec->ctx, scratch_x_q);
    id<MTLBuffer> b_xs  = rec_pick(rec->ctx, scratch_x_scales);
    if (!b_x || !b_w || !b_ws || !b_out || !b_xq || !b_xs) return -1;

    uint M_u = (uint)M, N_u = (uint)N;
    /* Encoder 1: quantize_input_int8_g128 */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_q];
        [enc setBuffer:b_x  offset:0 atIndex:0];
        [enc setBuffer:b_xq offset:0 atIndex:1];
        [enc setBuffer:b_xs offset:0 atIndex:2];
        [enc setBytes:&N_u length:sizeof(N_u) atIndex:3];
        NSUInteger nq = (NSUInteger)((N + 127) / 128);
        [enc dispatchThreadgroups:MTLSizeMake(nq, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        [enc endEncoding];
    }
    /* Encoder 2: matmul_w4a8 */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_mm];
        [enc setBuffer:b_w   offset:0 atIndex:0];
        [enc setBuffer:b_ws  offset:0 atIndex:1];
        [enc setBuffer:b_xq  offset:0 atIndex:2];
        [enc setBuffer:b_xs  offset:0 atIndex:3];
        [enc setBuffer:b_out offset:0 atIndex:4];
        [enc setBytes:&M_u length:sizeof(M_u) atIndex:5];
        [enc setBytes:&N_u length:sizeof(N_u) atIndex:6];
        const NSUInteger SIMDS_PER_TG = 4;
        const NSUInteger TG_THREADS = 32 * SIMDS_PER_TG;
        NSUInteger n_tg = (M + SIMDS_PER_TG - 1) / SIMDS_PER_TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG_THREADS, 1, 1)];
        [enc endEncoding];
    }
    return 0;
}

extern "C" int ib_metal_rec_matmul_w4a8_blk32_fp32_in(ib_metal_recorder *rec,
                                                        const void *x_fp32,
                                                        const void *weights,
                                                        const void *w_scales,
                                                        void *out,
                                                        void *scratch_x_q,
                                                        void *scratch_x_scales,
                                                        int M, int N)
{
    if (!rec || !x_fp32 || !weights || !w_scales || !out
        || !scratch_x_q || !scratch_x_scales || M <= 0 || N <= 0) return -1;
    if ((N % 32) != 0) return -1;
    id<MTLComputePipelineState> ps_q  = get_pipeline(rec->ctx, "quantize_input_int8_g128");
    /* Default: the "deferred reduction" kernel (1 simd_sum per output
     * row instead of 64 — one per block). +6-9% decode tok/s across
     * all 3 GPU blk32 cells, no regression observed. IB_DECODE_DR=0
     * forces the legacy per-block-reduce kernel for A/B comparison. */
    static int dr_setting = -1;
    if (dr_setting < 0) {
        const char *env = getenv("IB_DECODE_DR");
        dr_setting = (env && env[0] == '0') ? 0 : 1;
    }
    id<MTLComputePipelineState> ps_mm = get_pipeline(rec->ctx,
        dr_setting ? "matmul_w4a8_blk32_dr" : "matmul_w4a8_blk32");
    if (!ps_q || !ps_mm) return -1;

    id<MTLBuffer> b_x   = rec_pick(rec->ctx, x_fp32);
    id<MTLBuffer> b_w   = rec_pick(rec->ctx, weights);
    id<MTLBuffer> b_ws  = rec_pick(rec->ctx, w_scales);
    id<MTLBuffer> b_out = rec_pick(rec->ctx, out);
    id<MTLBuffer> b_xq  = rec_pick(rec->ctx, scratch_x_q);
    id<MTLBuffer> b_xs  = rec_pick(rec->ctx, scratch_x_scales);
    if (!b_x || !b_w || !b_ws || !b_out || !b_xq || !b_xs) return -1;

    uint M_u = (uint)M, N_u = (uint)N;
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_q];
        [enc setBuffer:b_x  offset:0 atIndex:0];
        [enc setBuffer:b_xq offset:0 atIndex:1];
        [enc setBuffer:b_xs offset:0 atIndex:2];
        [enc setBytes:&N_u length:sizeof(N_u) atIndex:3];
        NSUInteger nq = (NSUInteger)((N + 127) / 128);
        [enc dispatchThreadgroups:MTLSizeMake(nq, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        [enc endEncoding];
    }
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_mm];
        [enc setBuffer:b_w   offset:0 atIndex:0];
        [enc setBuffer:b_ws  offset:0 atIndex:1];
        [enc setBuffer:b_xq  offset:0 atIndex:2];
        [enc setBuffer:b_xs  offset:0 atIndex:3];
        [enc setBuffer:b_out offset:0 atIndex:4];
        [enc setBytes:&M_u length:sizeof(M_u) atIndex:5];
        [enc setBytes:&N_u length:sizeof(N_u) atIndex:6];
        const NSUInteger SIMDS_PER_TG = 4;
        const NSUInteger TG_THREADS = 32 * SIMDS_PER_TG;
        NSUInteger n_tg = (M + SIMDS_PER_TG - 1) / SIMDS_PER_TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG_THREADS, 1, 1)];
        [enc endEncoding];
    }
    return 0;
}

