/* Same shape as ib_metal_rec_matmul_w4a8_blk32_batched_fp32_in but uses
 * Apple's simdgroup_matrix_multiply hardware unit. Requires B and M
 * each be multiples of 8 (single-tile dispatch, no edge handling). */
extern "C" int ib_metal_rec_matmul_w4a8_blk32_batched_simdmat_fp32_in(ib_metal_recorder *rec,
                                                                       const void *x_fp32,
