{
    if (!rec || !x_fp32 || !weights || !w_scales || !out
        || !scratch_x_q || !scratch_x_scales || B <= 0 || M <= 0 || N <= 0) return -1;
    if ((N % 128) != 0 || (M % 8) != 0 || (B % 8) != 0) return -2;
