    [enc dispatchThreads:MTLSizeMake((NSUInteger)N, (NSUInteger)B, 1)
       threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
    (void)n_tg_x;
    [enc endEncoding];
    return 0;
}

