/* Batched fp16-KV attention block: runs B prefill positions through
 * kv_write → scores → softmax → weighted_v in 4 dispatches total
 * (vs. 4×B in the per-position variant). Causal masking is handled by
 * the scores kernel writing -INFINITY to invalid (j > start_pos+b)
 * entries; softmax then produces 0 for those.
 *
 *   q, k, v       : float[B][n_heads*head_dim] (k/v use kv_dim cols)
 *   k_cache,v_cache: float[seq_len][kv_dim]
 *   scores        : float[B][n_heads][max_score_len]  (max_score_len = start_pos+B)
 *   attn_out      : float[B][n_heads*head_dim]
 */
extern "C" int ib_metal_rec_attention_block_fp16_batched(ib_metal_recorder *rec,
                                                            const void *q_fp32,
                                                            const void *k_fp32,
                                                            const void *v_fp32,
                                                            void *k_cache_fp16,
                                                            void *v_cache_fp16,
                                                            void *scores_fp32,
                                                            void *attn_out_fp32,
                                                            int B, int n_heads, int n_kv_heads,
                                                            int head_dim, int seq_len, int start_pos)
{
    if (!rec) return -1;
    if (!q_fp32 || !k_fp32 || !v_fp32 || !k_cache_fp16 || !v_cache_fp16
        || !scores_fp32 || !attn_out_fp32) return -1;
    if (B <= 0 || n_heads <= 0 || n_kv_heads <= 0 || head_dim <= 0 || seq_len <= 0) return -1;
    if (start_pos < 0 || start_pos + B > seq_len) return -1;
    if (n_heads % n_kv_heads != 0) return -1;

    id<MTLComputePipelineState> ps_write = get_pipeline(rec->ctx, "kv_cache_write_fp16_batched");
    id<MTLComputePipelineState> ps_score = get_pipeline(rec->ctx, "attn_scores_qk_batched");
    id<MTLComputePipelineState> ps_smax  = get_pipeline(rec->ctx, "softmax_rows");
    id<MTLComputePipelineState> ps_wv    = get_pipeline(rec->ctx, "attn_weighted_v_batched");
    if (!ps_write || !ps_score || !ps_smax || !ps_wv) return -1;

    NSUInteger oq=0, ok=0, ov=0, okc=0, ovc=0, os=0, oo=0;
    id<MTLBuffer> b_q  = rec_pick_off(rec->ctx, q_fp32, &oq);
    id<MTLBuffer> b_k  = rec_pick_off(rec->ctx, k_fp32, &ok);
    id<MTLBuffer> b_v  = rec_pick_off(rec->ctx, v_fp32, &ov);
    id<MTLBuffer> b_kc = rec_pick_off(rec->ctx, k_cache_fp16, &okc);
    id<MTLBuffer> b_vc = rec_pick_off(rec->ctx, v_cache_fp16, &ovc);
    id<MTLBuffer> b_s  = rec_pick_off(rec->ctx, scores_fp32, &os);
    id<MTLBuffer> b_o  = rec_pick_off(rec->ctx, attn_out_fp32, &oo);
    if (!b_q || !b_k || !b_v || !b_kc || !b_vc || !b_s || !b_o) return -1;

    uint B_u = (uint)B, nh = (uint)n_heads, nkh = (uint)n_kv_heads;
    uint hd = (uint)head_dim, sp = (uint)start_pos;
    uint max_score_len = sp + B_u;
    uint kv_dim = nkh * hd;
    float scale = 1.0f / sqrtf((float)head_dim);

    /* 1. KV write (B positions in parallel) */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_write];
        [enc setBuffer:b_k  offset:ok  atIndex:0];
        [enc setBuffer:b_v  offset:ov  atIndex:1];
        [enc setBuffer:b_kc offset:okc atIndex:2];
        [enc setBuffer:b_vc offset:ovc atIndex:3];
        [enc setBytes:&sp     length:sizeof(sp)     atIndex:4];
        [enc setBytes:&kv_dim length:sizeof(kv_dim) atIndex:5];
        [enc dispatchThreads:MTLSizeMake(kv_dim, (NSUInteger)B, 1)
           threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
        [enc endEncoding];
    }
    /* 2. Scores with causal masking */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_score];
        [enc setBuffer:b_q  offset:oq  atIndex:0];
        [enc setBuffer:b_kc offset:okc atIndex:1];
        [enc setBuffer:b_s  offset:os  atIndex:2];
        [enc setBytes:&nh length:sizeof(nh) atIndex:3];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:4];
        [enc setBytes:&hd length:sizeof(hd) atIndex:5];
        [enc setBytes:&max_score_len length:sizeof(max_score_len) atIndex:6];
        [enc setBytes:&sp length:sizeof(sp) atIndex:7];
        [enc setBytes:&scale length:sizeof(scale) atIndex:8];
        [enc dispatchThreads:MTLSizeMake(max_score_len, nh, (NSUInteger)B)
           threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        [enc endEncoding];
    }
    /* 3. Softmax over (B*n_heads) rows of length max_score_len */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_smax];
        [enc setBuffer:b_s offset:os atIndex:0];
        [enc setBytes:&max_score_len length:sizeof(max_score_len) atIndex:1];
        NSUInteger n_rows = (NSUInteger)B * nh;
        [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
    }
    /* 4. Weighted V (B*n_heads*head_dim cells) */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_wv];
        [enc setBuffer:b_s  offset:os  atIndex:0];
        [enc setBuffer:b_vc offset:ovc atIndex:1];
        [enc setBuffer:b_o  offset:oo  atIndex:2];
        [enc setBytes:&nh length:sizeof(nh) atIndex:3];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:4];
        [enc setBytes:&hd length:sizeof(hd) atIndex:5];
        [enc setBytes:&max_score_len length:sizeof(max_score_len) atIndex:6];
        [enc setBytes:&sp length:sizeof(sp) atIndex:7];
        [enc dispatchThreads:MTLSizeMake(hd, nh, (NSUInteger)B)
           threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
        [enc endEncoding];
    }
    return 0;
}

extern "C" int ib_metal_rec_attention_block_fp16(ib_metal_recorder *rec,
                                                   const void *q_fp32,
                                                   const void *k_fp32,
                                                   const void *v_fp32,
                                                   void *k_cache_fp16,
                                                   void *v_cache_fp16,
                                                   void *scores_fp32,
                                                   void *attn_out_fp32,
                                                   int n_heads, int n_kv_heads,
                                                   int head_dim, int seq_len, int pos)
{
    if (!rec) return -1;
    if (!q_fp32 || !k_fp32 || !v_fp32 || !k_cache_fp16 || !v_cache_fp16
        || !scores_fp32 || !attn_out_fp32) return -1;
    if (n_heads <= 0 || n_kv_heads <= 0 || head_dim <= 0 || seq_len <= 0) return -1;
    if (pos < 0 || pos >= seq_len) return -1;
    if (n_heads % n_kv_heads != 0) return -1;

    id<MTLComputePipelineState> ps_write = get_pipeline(rec->ctx, "kv_cache_write_fp16");
    id<MTLComputePipelineState> ps_score = get_pipeline(rec->ctx, "attn_scores_qk");
    id<MTLComputePipelineState> ps_smax  = get_pipeline(rec->ctx, "softmax_rows");
    id<MTLComputePipelineState> ps_wv    = get_pipeline(rec->ctx, "attn_weighted_v");
    if (!ps_write || !ps_score || !ps_smax || !ps_wv) return -1;

    NSUInteger oq=0, ok=0, ov=0, okc=0, ovc=0, os=0, oo=0;
    id<MTLBuffer> b_q  = rec_pick_off(rec->ctx, q_fp32, &oq);
    id<MTLBuffer> b_k  = rec_pick_off(rec->ctx, k_fp32, &ok);
    id<MTLBuffer> b_v  = rec_pick_off(rec->ctx, v_fp32, &ov);
    id<MTLBuffer> b_kc = rec_pick_off(rec->ctx, k_cache_fp16, &okc);
    id<MTLBuffer> b_vc = rec_pick_off(rec->ctx, v_cache_fp16, &ovc);
    id<MTLBuffer> b_s  = rec_pick_off(rec->ctx, scores_fp32, &os);
    id<MTLBuffer> b_o  = rec_pick_off(rec->ctx, attn_out_fp32, &oo);
    if (!b_q || !b_k || !b_v || !b_kc || !b_vc || !b_s || !b_o) return -1;

    uint nh = (uint)n_heads, nkh = (uint)n_kv_heads, hd = (uint)head_dim;
    uint p  = (uint)pos, p1 = (uint)pos + 1u;
    uint kv_dim = nkh * hd;
    float scale = 1.0f / sqrtf((float)head_dim);

    /* 1. KV write */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_write];
        [enc setBuffer:b_k  offset:ok  atIndex:0];
        [enc setBuffer:b_v  offset:ov  atIndex:1];
        [enc setBuffer:b_kc offset:okc atIndex:2];
        [enc setBuffer:b_vc offset:ovc atIndex:3];
        [enc setBytes:&p length:sizeof(p) atIndex:4];
        [enc setBytes:&kv_dim length:sizeof(kv_dim) atIndex:5];
        const NSUInteger TG = 64;
        NSUInteger n_tg = (kv_dim + TG - 1) / TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
        [enc endEncoding];
    }
    /* 2. Scores */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_score];
        [enc setBuffer:b_q  offset:oq  atIndex:0];
        [enc setBuffer:b_kc offset:okc atIndex:1];
        [enc setBuffer:b_s  offset:os  atIndex:2];
        [enc setBytes:&nh length:sizeof(nh) atIndex:3];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:4];
        [enc setBytes:&hd length:sizeof(hd) atIndex:5];
        [enc setBytes:&p1 length:sizeof(p1) atIndex:6];
        [enc setBytes:&scale length:sizeof(scale) atIndex:7];
        const NSUInteger TG = 128;
        NSUInteger total = (NSUInteger)nh * (NSUInteger)p1;
        NSUInteger n_tg = (total + TG - 1) / TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
        [enc endEncoding];
    }
    /* 3. Softmax */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_smax];
        [enc setBuffer:b_s offset:os atIndex:0];
        [enc setBytes:&p1 length:sizeof(p1) atIndex:1];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nh, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
    }
    /* 4. Weighted V */
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_wv];
        [enc setBuffer:b_s  offset:os  atIndex:0];
        [enc setBuffer:b_vc offset:ovc atIndex:1];
        [enc setBuffer:b_o  offset:oo  atIndex:2];
        [enc setBytes:&nh length:sizeof(nh) atIndex:3];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:4];
        [enc setBytes:&hd length:sizeof(hd) atIndex:5];
        [enc setBytes:&p1 length:sizeof(p1) atIndex:6];
        const NSUInteger TG = 64;
        NSUInteger total = (NSUInteger)nh * (NSUInteger)hd;
        NSUInteger n_tg = (total + TG - 1) / TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
        [enc endEncoding];
    }
    return 0;
}

extern "C" int ib_metal_rec_attention_block_int8(ib_metal_recorder *rec,
                                                   const void *q_fp32,
                                                   const void *k_fp32,
                                                   const void *v_fp32,
                                                   void *k_cache_int8,
                                                   void *v_cache_int8,
                                                   void *k_scales_fp32,
                                                   void *v_scales_fp32,
                                                   void *scores_fp32,
                                                   void *attn_out_fp32,
                                                   int n_heads, int n_kv_heads,
                                                   int head_dim, int seq_len, int pos)
{
    if (!rec) return -1;
    if (!q_fp32 || !k_fp32 || !v_fp32 || !k_cache_int8 || !v_cache_int8
        || !k_scales_fp32 || !v_scales_fp32 || !scores_fp32 || !attn_out_fp32) return -1;
    if (n_heads <= 0 || n_kv_heads <= 0 || head_dim <= 0 || seq_len <= 0) return -1;
    if (pos < 0 || pos >= seq_len) return -1;
    if (n_heads % n_kv_heads != 0) return -1;

    id<MTLComputePipelineState> ps_write = get_pipeline(rec->ctx, "kv_cache_write_int8");
    id<MTLComputePipelineState> ps_score = get_pipeline(rec->ctx, "attn_scores_qk_int8");
    id<MTLComputePipelineState> ps_smax  = get_pipeline(rec->ctx, "softmax_rows");
    id<MTLComputePipelineState> ps_wv    = get_pipeline(rec->ctx, "attn_weighted_v_int8");
    if (!ps_write || !ps_score || !ps_smax || !ps_wv) return -1;

    NSUInteger oq=0, ok=0, ov=0, okc=0, ovc=0, oks=0, ovs=0, os=0, oo=0;
    id<MTLBuffer> b_q  = rec_pick_off(rec->ctx, q_fp32, &oq);
    id<MTLBuffer> b_k  = rec_pick_off(rec->ctx, k_fp32, &ok);
    id<MTLBuffer> b_v  = rec_pick_off(rec->ctx, v_fp32, &ov);
    id<MTLBuffer> b_kc = rec_pick_off(rec->ctx, k_cache_int8, &okc);
    id<MTLBuffer> b_vc = rec_pick_off(rec->ctx, v_cache_int8, &ovc);
    id<MTLBuffer> b_ks = rec_pick_off(rec->ctx, k_scales_fp32, &oks);
    id<MTLBuffer> b_vs = rec_pick_off(rec->ctx, v_scales_fp32, &ovs);
    id<MTLBuffer> b_s  = rec_pick_off(rec->ctx, scores_fp32, &os);
    id<MTLBuffer> b_o  = rec_pick_off(rec->ctx, attn_out_fp32, &oo);
    if (!b_q || !b_k || !b_v || !b_kc || !b_vc || !b_ks || !b_vs || !b_s || !b_o) return -1;

    uint nh = (uint)n_heads, nkh = (uint)n_kv_heads, hd = (uint)head_dim;
    uint p = (uint)pos, p1 = (uint)pos + 1u;
    float scale = 1.0f / sqrtf((float)head_dim);

    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_write];
        [enc setBuffer:b_k  offset:ok  atIndex:0];
        [enc setBuffer:b_v  offset:ov  atIndex:1];
        [enc setBuffer:b_kc offset:okc atIndex:2];
        [enc setBuffer:b_vc offset:ovc atIndex:3];
        [enc setBuffer:b_ks offset:oks atIndex:4];
        [enc setBuffer:b_vs offset:ovs atIndex:5];
        [enc setBytes:&p   length:sizeof(p)   atIndex:6];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:7];
        [enc setBytes:&hd  length:sizeof(hd)  atIndex:8];
        [enc dispatchThreadgroups:MTLSizeMake(nkh, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        [enc endEncoding];
    }
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_score];
        [enc setBuffer:b_q  offset:oq  atIndex:0];
        [enc setBuffer:b_kc offset:okc atIndex:1];
        [enc setBuffer:b_ks offset:oks atIndex:2];
        [enc setBuffer:b_s  offset:os  atIndex:3];
        [enc setBytes:&nh length:sizeof(nh) atIndex:4];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:5];
        [enc setBytes:&hd length:sizeof(hd) atIndex:6];
        [enc setBytes:&p1 length:sizeof(p1) atIndex:7];
        [enc setBytes:&scale length:sizeof(scale) atIndex:8];
        const NSUInteger TG = 128;
        NSUInteger total = (NSUInteger)nh * (NSUInteger)p1;
        NSUInteger n_tg = (total + TG - 1) / TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
        [enc endEncoding];
    }
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_smax];
        [enc setBuffer:b_s offset:os atIndex:0];
        [enc setBytes:&p1 length:sizeof(p1) atIndex:1];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nh, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
    }
    {
        id<MTLComputeCommandEncoder> enc = [rec->cb computeCommandEncoder];
        [enc setComputePipelineState:ps_wv];
        [enc setBuffer:b_s  offset:os  atIndex:0];
        [enc setBuffer:b_vc offset:ovc atIndex:1];
        [enc setBuffer:b_vs offset:ovs atIndex:2];
        [enc setBuffer:b_o  offset:oo  atIndex:3];
        [enc setBytes:&nh length:sizeof(nh) atIndex:4];
        [enc setBytes:&nkh length:sizeof(nkh) atIndex:5];
        [enc setBytes:&hd length:sizeof(hd) atIndex:6];
        [enc setBytes:&p1 length:sizeof(p1) atIndex:7];
        const NSUInteger TG = 64;
        NSUInteger total = (NSUInteger)nh * (NSUInteger)hd;
        NSUInteger n_tg = (total + TG - 1) / TG;
        [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
        [enc endEncoding];
    }
    return 0;
}

extern "C" int ib_metal_attention_block_fp16(ib_metal_ctx *ctx,
                                               const void *q_fp32,
                                               const void *k_fp32,
                                               const void *v_fp32,
                                               void *k_cache_fp16,
                                               void *v_cache_fp16,
                                               void *scores_fp32,
                                               void *attn_out_fp32,
                                               int n_heads, int n_kv_heads,
                                               int head_dim, int seq_len, int pos)
{
    if (!ctx) return -1;
    if (!q_fp32 || !k_fp32 || !v_fp32 || !k_cache_fp16 || !v_cache_fp16
        || !scores_fp32 || !attn_out_fp32) return -1;
    if (n_heads <= 0 || n_kv_heads <= 0 || head_dim <= 0 || seq_len <= 0) return -1;
    if (pos < 0 || pos >= seq_len) return -1;
    if (n_heads % n_kv_heads != 0) return -1;

    @autoreleasepool {
        id<MTLComputePipelineState> ps_write = get_pipeline(ctx, "kv_cache_write_fp16");
        id<MTLComputePipelineState> ps_score = get_pipeline(ctx, "attn_scores_qk");
        id<MTLComputePipelineState> ps_smax  = get_pipeline(ctx, "softmax_rows");
        id<MTLComputePipelineState> ps_wv    = get_pipeline(ctx, "attn_weighted_v");
        if (!ps_write || !ps_score || !ps_smax || !ps_wv) return -1;

        auto pick = [&](const void *p) -> id<MTLBuffer> {
            auto it = ctx->buffers.find((void *)p);
            return it == ctx->buffers.end() ? nil : it->second;
        };
        id<MTLBuffer> b_q  = pick(q_fp32);
        id<MTLBuffer> b_k  = pick(k_fp32);
        id<MTLBuffer> b_v  = pick(v_fp32);
        id<MTLBuffer> b_kc = pick(k_cache_fp16);
        id<MTLBuffer> b_vc = pick(v_cache_fp16);
        id<MTLBuffer> b_s  = pick(scores_fp32);
        id<MTLBuffer> b_o  = pick(attn_out_fp32);
        if (!b_q || !b_k || !b_v || !b_kc || !b_vc || !b_s || !b_o) {
            fprintf(stderr, "Metal attn: buffer not registered\n");
            return -1;
        }

        uint nh = (uint)n_heads, nkh = (uint)n_kv_heads, hd = (uint)head_dim;
        uint p = (uint)pos, p1 = (uint)pos + 1u;
        uint kv_dim = nkh * hd;
        uint sl = (uint)seq_len;
        float scale = 1.0f / sqrtf((float)head_dim);

        id<MTLCommandBuffer> cb = [ctx->queue commandBuffer];

        /* 1. KV write at row `pos`. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_write];
            [enc setBuffer:b_k  offset:0 atIndex:0];
            [enc setBuffer:b_v  offset:0 atIndex:1];
            [enc setBuffer:b_kc offset:0 atIndex:2];
            [enc setBuffer:b_vc offset:0 atIndex:3];
            [enc setBytes:&p      length:sizeof(p)      atIndex:4];
            [enc setBytes:&kv_dim length:sizeof(kv_dim) atIndex:5];
            const NSUInteger TG = 64;
            NSUInteger n_tg = (kv_dim + TG - 1) / TG;
            [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
            [enc endEncoding];
        }
        /* 2. Scores: scores[h, t] for h in n_heads, t in [0, pos]. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_score];
            [enc setBuffer:b_q  offset:0 atIndex:0];
            [enc setBuffer:b_kc offset:0 atIndex:1];
            [enc setBuffer:b_s  offset:0 atIndex:2];
            [enc setBytes:&nh    length:sizeof(nh)    atIndex:3];
            [enc setBytes:&nkh   length:sizeof(nkh)   atIndex:4];
            [enc setBytes:&hd    length:sizeof(hd)    atIndex:5];
            [enc setBytes:&p1    length:sizeof(p1)    atIndex:6];
            [enc setBytes:&scale length:sizeof(scale) atIndex:7];
            const NSUInteger TG = 128;
            NSUInteger total = (NSUInteger)nh * (NSUInteger)p1;
            NSUInteger n_tg = (total + TG - 1) / TG;
            [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
            [enc endEncoding];
        }
        /* 3. Softmax over each row of `scores`. NOTE: scores buffer is
         *    [n_heads, seq_len] but softmax sees row_len=p1 — so it only
         *    reads/writes the active prefix and ignores the unused tail.
         *    Trick: we pass row_len=p1 and dispatch n_rows=n_heads, but
         *    the row stride must match — so we treat the buffer as a
         *    contiguous [n_heads, p1]. We achieve this by writing the
         *    scores in [n_heads, p1] layout in the previous pass (we did:
         *    scores[h * p1 + t]). */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_smax];
            [enc setBuffer:b_s offset:0 atIndex:0];
            [enc setBytes:&p1  length:sizeof(p1) atIndex:1];
            [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nh, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            [enc endEncoding];
        }
        /* 4. Weighted sum over V to get attn_out. */
        {
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:ps_wv];
            [enc setBuffer:b_s  offset:0 atIndex:0];
            [enc setBuffer:b_vc offset:0 atIndex:1];
            [enc setBuffer:b_o  offset:0 atIndex:2];
            [enc setBytes:&nh  length:sizeof(nh)  atIndex:3];
            [enc setBytes:&nkh length:sizeof(nkh) atIndex:4];
            [enc setBytes:&hd  length:sizeof(hd)  atIndex:5];
            [enc setBytes:&p1  length:sizeof(p1)  atIndex:6];
            const NSUInteger TG = 64;
            NSUInteger total = (NSUInteger)nh * (NSUInteger)hd;
            NSUInteger n_tg = (total + TG - 1) / TG;
            [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                  threadsPerThreadgroup:MTLSizeMake(TG, 1, 1)];
            [enc endEncoding];
        }

        [cb commit];
        [cb waitUntilCompleted];
        if (cb.status == MTLCommandBufferStatusError) {
            fprintf(stderr, "Metal attn: cmd buffer error: %s\n",
                    [[cb.error localizedDescription] UTF8String]);
            return -1;
        }
        (void)sl;  /* seq_len unused inside kernels; cache stride is kv_dim */
    }
    return 0;
}
